using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace Kit.CodeShape;

/// <summary>Whether a file is generated code, by the C# compiler's own test, which its analyzers use to skip such
/// files: a name starting TemporaryGeneratedFile_ or ending .designer.cs, .generated.cs, .g.cs or .g.i.cs, or an
/// &lt;auto-generated&gt; comment before the file's first token
/// (https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/compiler-options/language#nullable).</summary>
internal static class GeneratedCode
{
    private static readonly string[] s_suffixes = [".designer.cs", ".generated.cs", ".g.cs", ".g.i.cs"];

    public static bool Is(SourceFile file)
    {
        ArgumentNullException.ThrowIfNull(file);

        string name = Path.GetFileName(file.Path);
        return name.StartsWith("TemporaryGeneratedFile_", StringComparison.OrdinalIgnoreCase)
            || s_suffixes.Any(suffix => name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
            || HasGeneratedHeader(file.Parse());
    }

    private static bool HasGeneratedHeader(SyntaxTree tree) =>
        tree.GetRoot().GetLeadingTrivia()
            .Where(trivia => trivia.IsKind(SyntaxKind.SingleLineCommentTrivia) || trivia.IsKind(SyntaxKind.MultiLineCommentTrivia))
            .Any(trivia => trivia.ToString().Contains("<auto-generated", StringComparison.Ordinal)
                || trivia.ToString().Contains("<autogenerated", StringComparison.Ordinal));
}
